import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;
type DecodeVariant = 'all' | 'greedy' | 'topk' | 'topp' | 'beam';

const W = 1120;
const CX = W / 2;
const BOX_H = 76;
const STEP_GAP = 300;
const BOX_TO_ROW = 180;
const SHAPE_GAP = 80;
const VEC_W = 640;
const VEC_H = 56;
const SCALAR_SIZE = 64;
const ARROW_MARGIN = 22;

const COLORS = {
  logits:  { fill: '#e3f2fd', stroke: '#1976d2' },
  scaled:  { fill: '#e8f5e9', stroke: '#4caf50' },
  probs:   { fill: '#fff3e0', stroke: '#f57c00' },
  greedy:  { fill: '#e3f2fd', stroke: '#1565c0' },
  topk:    { fill: '#f3e5f5', stroke: '#7b1fa2' },
  topp:    { fill: '#ffebee', stroke: '#c62828' },
  beam:    { fill: '#e0f2f1', stroke: '#00838f' },
  muted: 'var(--text-muted)' as string,
};

interface DecodeStep extends StepInfo {}

function lbl(g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void { drawLabel(g as Sel, x, y, text, opts); }

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = W - 80): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 26).attr('cy', y + BOX_H / 2)
    .attr('r', 15).attr('fill', stroke);
  lbl(g, cx - w / 2 + 26, y + BOX_H / 2 + 1, String(sn), { size: 13, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 - 6, title, { size: 14, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 + 12, formula, { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 7.5 + 48, 280);
  const h = 34;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 11, color, font: 'monospace' });
}

function sampleNote(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 32, 180);
  const h = 22;
  g.append('rect')
    .attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color)
    .attr('stroke-width', 0.5).attr('opacity', 0.88);
  lbl(g, cx, cy + 1, text, { size: 9, color, font: 'monospace' });
}

function smallNote(g: Gsel, x: number, y: number, text: string, color: string, anchor: 'start' | 'middle' | 'end' = 'start'): void {
  lbl(g, x, y, text, { size: 9, color, anchor, font: 'monospace' });
}

function opBox(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 9 + 28, 64);
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 13, weight: '700', color });
}

function arrowWithLabel(g: Gsel, x1: number, y1: number, x2: number, y2: number,
  color: string, label: string, labelPos: 'start' | 'middle' | 'end' = 'middle'): void {
  drawArrow(g as Sel, x1, y1, x2, y2, { color });
  const lx = labelPos === 'start' ? x1 + (x2 - x1) * 0.25 : labelPos === 'end' ? x1 + (x2 - x1) * 0.75 : (x1 + x2) / 2;
  const ly = (y1 + y2) / 2;
  // offset label to the right-hand side of the arrow direction so it never sits on the line
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.sqrt(dx * dx + dy * dy) || 1;
  const ox = (dy / len) * 22;
  const oy = (-dx / len) * 22;
  smallNote(g, lx + ox, ly + oy, label, color, 'middle');
}

function arrowH(g: Gsel, xFrom: number, xTo: number, y: number, color = '#94a3b8', margin = ARROW_MARGIN): void {
  const dir = xTo >= xFrom ? 1 : -1;
  drawArrow(g as Sel, xFrom + dir * margin, y, xTo - dir * margin, y, { color });
}

function makeLCG(seed: number) {
  let s = seed | 0;
  return () => { s = (s * 1664525 + 1013904223) | 0; return ((s >>> 0) / 4294967296); };
}

function makeStep(id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]): DecodeStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function tokenBar(g: Gsel, cx: number, cy: number, values: number[], colors: string[],
  labelAbove?: string, labelBelow?: string): void {
  const n = values.length;
  const cellW = VEC_W / n;
  const leftX = cx - VEC_W / 2;
  if (labelAbove) lbl(g, cx, cy - VEC_H / 2 - 12, labelAbove, { size: 9, color: COLORS.muted, font: 'monospace' });
  for (let i = 0; i < n; i++) {
    const x = leftX + i * cellW;
    g.append('rect').attr('x', x + 1).attr('y', cy - VEC_H / 2 + 1)
      .attr('width', cellW - 2).attr('height', VEC_H - 2)
      .attr('rx', 2).attr('fill', colors[i]).attr('stroke', '#fff').attr('stroke-width', 1);
  }
  if (labelBelow) lbl(g, cx, cy + VEC_H / 2 + 14, labelBelow, { size: 9, color: COLORS.muted, font: 'monospace' });
}

function scalarBlock(g: Gsel, cx: number, cy: number, label: string, sub = '', fill?: string, stroke?: string): void {
  drawMatrixBlock(g as Sel, cx - SCALAR_SIZE / 2, cy - SCALAR_SIZE / 2, {
    width: SCALAR_SIZE, height: SCALAR_SIZE, label, sublabel: sub,
    fill: fill || COLORS.probs.fill, stroke: stroke || COLORS.probs.stroke,
    cols: 1, rows: 1,
  });
}

function argsortDesc(arr: number[]): number[] {
  return arr.map((v, i) => ({ v, i })).sort((a, b) => b.v - a.v).map((x) => x.i);
}

/**
 * Build a deterministic, illustration-friendly vocabulary distribution.
 * Sorted probabilities decay geometrically so that top-p ≈ 0.9 is reached
 * in about 7 tokens, giving a clear nucleus curve while still summing to 1.
 */
function makeDecodingProbs(fullV: number, temperature: number) {
  const lambda = 3.0;
  const pMin = 1e-6;
  const raw: number[] = [];
  let rawSum = 0;
  for (let i = 0; i < fullV; i++) {
    const p = Math.max(pMin, Math.exp(-i / lambda) * (1 - Math.exp(-1 / lambda)));
    raw.push(p);
    rawSum += p;
  }
  const targetProbs = raw.map((p) => p / rawSum);
  let scaledSorted = targetProbs.map((p) => Math.log(p));
  // shift so the largest scaled logit is ~3.75 (matches the old random-logit range after T=0.8)
  const shift = 3.75 - Math.max(...scaledSorted);
  scaledSorted = scaledSorted.map((s) => s + shift);
  const logitsSorted = scaledSorted.map((s) => s * temperature);

  // deterministic shuffle so the input bar looks like an unordered vocabulary
  const shuffleRng = makeLCG(2024);
  const shuffleKeys = Array.from({ length: fullV }, () => shuffleRng());
  const order = argsortDesc(shuffleKeys);

  const logits: number[] = new Array(fullV);
  const scaled: number[] = new Array(fullV);
  const probs: number[] = new Array(fullV);
  order.forEach((srcIdx, destIdx) => {
    logits[destIdx] = logitsSorted[srcIdx];
    scaled[destIdx] = scaledSorted[srcIdx];
    probs[destIdx] = targetProbs[srcIdx];
  });
  return { logits, scaled, probs };
}

function probColors(probs: number[], stroke: string): string[] {
  const maxP = Math.max(...probs);
  return probs.map((p) => d3.interpolate('#fff', stroke)(Math.min(1, p / (maxP || 1))));
}

// ═══════════════════════════════════════════════════════════════════════════════
// Shared steps
// ═══════════════════════════════════════════════════════════════════════════════

function renderInputStep(g: Gsel, yStart: number, fullV: number, showV: number,
  logits: number[]): { step: DecodeStep; y: number } {
  const stepId = 1;
  const gs = startGroup(g, 'step-input', stepId);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Input Logits',
    `logits [1, ${fullV}]  —  raw scores for every token`,
    COLORS.logits.fill, COLORS.logits.stroke);
  const rowY = hBottom + BOX_TO_ROW;

  const colors = logits.slice(0, showV).map((v) => d3.interpolate('#fff', COLORS.logits.stroke)(Math.min(1, Math.abs(v) / 4)));
  tokenBar(gs, CX, rowY, logits.slice(0, showV), colors,
    `logits (first ${showV} of ${fullV} tokens)`,
    `range [${Math.min(...logits).toFixed(2)}, ${Math.max(...logits).toFixed(2)}]`);

  shapeEq(gs, CX, rowY + VEC_H / 2 + 28,
    `logits_i  =  un-normalized score of token i`, COLORS.logits.stroke);
  sampleNote(gs, CX, rowY + VEC_H / 2 + 28 + 26,
    `e.g. token 3 = ${logits[3].toFixed(2)}, token 7 = ${logits[7].toFixed(2)}`, COLORS.logits.stroke);

  const step = makeStep(stepId, 'Input', 'Input Logits',
    `logits [1, ${fullV}]`,
    `The language model outputs a logit score for every token in the vocabulary. Higher logits indicate more likely tokens, but these raw scores are not yet probabilities.`,
    'step-input', COLORS.logits.stroke, COLORS.logits.fill,
    [`logits = model(input_ids)  # [1, ${fullV}]`]);

  return { step, y: rowY + VEC_H / 2 + 28 + 26 + SHAPE_GAP + STEP_GAP };
}

function renderTemperatureStep(g: Gsel, yStart: number, fullV: number, showV: number,
  logits: number[], scaled: number[], temperature: number): { step: DecodeStep; y: number } {
  const stepId = 2;
  const gs = startGroup(g, 'step-temperature', stepId);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Temperature Scaling',
    `scaled = logits / T   (T = ${temperature})`,
    COLORS.scaled.fill, COLORS.scaled.stroke);
  const rowY = hBottom + BOX_TO_ROW;

  const inColors = logits.slice(0, showV).map((v) => d3.interpolate('#fff', COLORS.logits.stroke)(Math.min(1, Math.abs(v) / 4)));
  const outColors = scaled.slice(0, showV).map((v) => d3.interpolate('#fff', COLORS.scaled.stroke)(Math.min(1, Math.abs(v) / 5)));

  const inY = rowY;
  const opY = inY + 95;
  const outY = opY + 95;

  tokenBar(gs, CX, inY, logits.slice(0, showV), inColors, 'logits');
  opBox(gs, CX, opY, `/ ${temperature}`, COLORS.scaled.stroke);
  tokenBar(gs, CX, outY, scaled.slice(0, showV), outColors,
    'scaled logits', `each value multiplied by 1/${temperature}`);

  // clean vertical arrows with labels offset to the right
  arrowWithLabel(gs, CX, inY + VEC_H / 2 + 8, CX, opY - 20,
    COLORS.logits.stroke, 'logits_i', 'start');
  arrowWithLabel(gs, CX, opY + 20, CX, outY - VEC_H / 2 - 8,
    COLORS.scaled.stroke, `× 1/${temperature}`, 'end');

  shapeEq(gs, CX, outY + VEC_H / 2 + 30,
    `scaled_i = logits_i / ${temperature}`, COLORS.scaled.stroke);
  sampleNote(gs, CX, outY + VEC_H / 2 + 30 + 28,
    `${temperature < 1 ? 'T < 1 sharpens' : temperature > 1 ? 'T > 1 flattens' : 'T = 1 leaves unchanged'} the distribution`, COLORS.scaled.stroke);

  const step = makeStep(stepId, 'Temperature', 'Temperature Scaling',
    `scaled = logits / ${temperature}`,
    `Temperature rescales the logits before softmax. T < 1 makes the distribution sharper (more confident), T > 1 makes it flatter (more random), and T = 1 leaves it unchanged.`,
    'step-temperature', COLORS.scaled.stroke, COLORS.scaled.fill,
    [`scaled = logits / ${temperature}  # [1, ${fullV}]`]);

  return { step, y: outY + VEC_H / 2 + 30 + 28 + SHAPE_GAP + STEP_GAP };
}

function renderSoftmaxStep(g: Gsel, yStart: number, fullV: number, showV: number,
  scaled: number[], probs: number[]): { step: DecodeStep; y: number } {
  const stepId = 3;
  const gs = startGroup(g, 'step-softmax', stepId);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Softmax over Vocabulary',
    `probs = softmax(scaled)  —  sums to 1`,
    COLORS.probs.fill, COLORS.probs.stroke);
  const rowY = hBottom + BOX_TO_ROW;

  const inColors = scaled.slice(0, showV).map((v) => d3.interpolate('#fff', COLORS.scaled.stroke)(Math.min(1, Math.abs(v) / 5)));
  const outColors = probColors(probs.slice(0, showV), COLORS.probs.stroke);

  const inY = rowY;
  const chainY = inY + 95;
  const outY = chainY + 95;

  tokenBar(gs, CX, inY, scaled.slice(0, showV), inColors, 'scaled logits');

  const boxSpacing = 170;
  const boxes = [
    { label: 'exp', sub: 'elementwise', x: CX - boxSpacing },
    { label: 'Σ exp', sub: 'normalizer', x: CX },
    { label: '÷', sub: 'normalize', x: CX + boxSpacing },
  ];
  boxes.forEach((b) => opBox(gs, b.x, chainY, b.label, COLORS.probs.stroke));
  boxes.forEach((b) => smallNote(gs, b.x, chainY + 26, b.sub, COLORS.probs.stroke, 'middle'));
  arrowH(gs, CX - boxSpacing + 36, CX - 36, chainY, COLORS.probs.stroke);
  arrowH(gs, CX + 36, CX + boxSpacing - 36, chainY, COLORS.probs.stroke);

  tokenBar(gs, CX, outY, probs.slice(0, showV), outColors,
    'probabilities', `sum = 1.0000, max token = ${argsortDesc(probs)[0]}`);

  // annotate top-3 probabilities directly above their bars
  const top3 = argsortDesc(probs).slice(0, 3);
  const cellW = VEC_W / showV;
  const leftX = CX - VEC_W / 2;
  top3.forEach((idx, rank) => {
    const x = leftX + idx * cellW + cellW / 2;
    smallNote(gs, x, outY - VEC_H / 2 - 24, `p${rank + 1}=${probs[idx].toFixed(3)}`, COLORS.probs.stroke, 'middle');
  });

  // arrows from input bar to first op and from last op to output bar
  arrowWithLabel(gs, CX - boxSpacing, inY + VEC_H / 2 + 8, CX - boxSpacing, chainY - 20,
    COLORS.scaled.stroke, 'scaled_i', 'start');
  arrowWithLabel(gs, CX + boxSpacing, chainY + 20, CX + boxSpacing, outY - VEC_H / 2 - 8,
    COLORS.probs.stroke, 'p_i', 'end');

  shapeEq(gs, CX, outY + VEC_H / 2 + 30,
    `p_i = exp(scaled_i) / Σ_j exp(scaled_j)`, COLORS.probs.stroke);
  sampleNote(gs, CX, outY + VEC_H / 2 + 30 + 28,
    `all ${fullV} probabilities sum to 1; relative bar heights guide token selection`, COLORS.probs.stroke);

  const step = makeStep(stepId, 'Softmax', 'Softmax over Vocabulary',
    `probs = softmax(scaled)`,
    `Softmax converts scaled logits into a valid probability distribution over the vocabulary. The visualization normalizes cell colors by the maximum probability so that the shape of the distribution remains readable even when individual probabilities are small.`,
    'step-softmax', COLORS.probs.stroke, COLORS.probs.fill,
    [`probs = F.softmax(scaled, dim=-1)  # [1, ${fullV}]`]);

  return { step, y: outY + VEC_H / 2 + 30 + 28 + SHAPE_GAP + STEP_GAP };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant-specific steps
// ═══════════════════════════════════════════════════════════════════════════════

function renderGreedyStep(g: Gsel, yStart: number, fullV: number, showV: number,
  probs: number[]): { step: DecodeStep; y: number } {
  const stepId = 4;
  const gs = startGroup(g, 'step-greedy', stepId);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Greedy Decoding',
    `token = argmax(probs)  —  deterministic`,
    COLORS.greedy.fill, COLORS.greedy.stroke);
  const rowY = hBottom + BOX_TO_ROW;

  const sortedIdx = argsortDesc(probs);
  const sortedProbs = sortedIdx.slice(0, showV).map((i) => probs[i]);
  const topIdx = sortedIdx[0];
  const colors = probColors(sortedProbs, COLORS.probs.stroke);
  colors[0] = COLORS.greedy.stroke;

  const barY = rowY;
  const blockY = barY + 110;

  tokenBar(gs, CX, barY, sortedProbs, colors,
    `sorted probabilities (first ${showV} of ${fullV})`,
    `selected token ${topIdx} (p = ${probs[topIdx].toFixed(4)})`);

  // argmax marker over first cell
  const cellW = VEC_W / showV;
  const leftX = CX - VEC_W / 2;
  const selX = leftX + cellW / 2;
  g.append('polygon')
    .attr('points', `${selX - 7},${barY - VEC_H / 2 - 18} ${selX + 7},${barY - VEC_H / 2 - 18} ${selX},${barY - VEC_H / 2 - 6}`)
    .attr('fill', COLORS.greedy.stroke);
  smallNote(gs, selX, barY - VEC_H / 2 - 26, 'argmax', COLORS.greedy.stroke, 'middle');

  scalarBlock(gs, CX, blockY, `token ${topIdx}`, `p=${probs[topIdx].toFixed(3)}`, COLORS.greedy.fill, COLORS.greedy.stroke);
  arrowWithLabel(gs, selX, barY + VEC_H / 2 + 10, CX, blockY - SCALAR_SIZE / 2 - 6,
    COLORS.greedy.stroke, 'max index', 'middle');

  shapeEq(gs, CX, blockY + SCALAR_SIZE / 2 + 32,
    `token = argmax_i(p_i)`, COLORS.greedy.stroke);
  sampleNote(gs, CX, blockY + SCALAR_SIZE / 2 + 32 + 28,
    `always picks the highest-probability token — fast but can be repetitive`, COLORS.greedy.stroke);

  const step = makeStep(stepId, 'Greedy', 'Greedy Decoding',
    `token = argmax(probs)`,
    `Greedy decoding deterministically selects the token with the highest probability. It is simple and fast but tends to produce generic, repetitive text because it never takes randomness into account.`,
    'step-greedy', COLORS.greedy.stroke, COLORS.greedy.fill,
    [`token = probs.argmax(dim=-1)  # always the max`]);

  return { step, y: blockY + SCALAR_SIZE / 2 + 32 + 28 + SHAPE_GAP + STEP_GAP };
}

function renderTopKStep(g: Gsel, yStart: number, fullV: number, showV: number,
  probs: number[], topK: number): { step: DecodeStep; y: number } {
  const stepId = 5;
  const gs = startGroup(g, 'step-topk', stepId);
  const k = Math.min(topK, showV);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Top-K Sampling',
    `restrict to top-${topK} tokens, mask others, re-normalize, then sample`,
    COLORS.topk.fill, COLORS.topk.stroke);
  const rowY = hBottom + BOX_TO_ROW;

  const sortedIdx = argsortDesc(probs);
  const sortedFullProbs = sortedIdx.map((i) => probs[i]);
  const sortedProbs = sortedFullProbs.slice(0, showV);
  const effectiveK = Math.min(topK, fullV);
  const baseColors = probColors(sortedProbs, COLORS.probs.stroke);
  const barColors = sortedIdx.slice(0, showV).map((_, rank) =>
    rank < effectiveK ? baseColors[rank] : '#f5f5f5'
  );

  const bar1Y = rowY;
  const maskY = bar1Y + 110;
  const bar2Y = maskY + 90;
  const sampleY = bar2Y + 100;

  // original sorted probabilities with cutoff
  tokenBar(gs, CX, bar1Y, sortedProbs, barColors,
    `sorted probabilities (descending, showing top-${k} of ${fullV})`,
    `top-${topK} kept (purple); rank ≥ ${topK} masked to 0 (grey)`);

  // cutoff line and label when the conceptual top-K cutoff is visible
  const cellW = VEC_W / showV;
  const leftX = CX - VEC_W / 2;
  if (effectiveK < showV) {
    const cutoffX = leftX + effectiveK * cellW;
    g.append('line')
      .attr('x1', cutoffX).attr('y1', bar1Y - VEC_H / 2 - 10)
      .attr('x2', cutoffX).attr('y2', bar1Y + VEC_H / 2 + 10)
      .attr('stroke', COLORS.topk.stroke).attr('stroke-width', 2).attr('stroke-dasharray', '4 3');
    smallNote(gs, cutoffX + 8, bar1Y - VEC_H / 2 - 12, `rank=${effectiveK} cutoff`, COLORS.topk.stroke, 'start');
  }

  // mask operation box
  smallNote(gs, CX, maskY - 26, `mask rank(i) ≥ ${topK}`, COLORS.topk.stroke, 'middle');
  opBox(gs, CX, maskY, `keep top-${topK}`, COLORS.topk.stroke);

  // re-normalized top-k probabilities (conceptual mask over top-${topK}, displayed top-${showV})
  const topkSum = sortedFullProbs.slice(0, effectiveK).reduce((a, b) => a + b, 0);
  const renormFull = sortedProbs.map((p, i) => (i < effectiveK ? p / topkSum : 0));
  const renormBaseColors = probColors(renormFull.filter((p) => p > 0), COLORS.topk.stroke);
  const renormColors = sortedIdx.slice(0, showV).map((_, rank) =>
    rank < effectiveK ? renormBaseColors[rank] : '#f5f5f5'
  );
  tokenBar(gs, CX, bar2Y, renormFull, renormColors,
    `re-normalized probabilities within top-${topK}`,
    `sum of top-${topK} = ${topkSum.toFixed(4)} → re-normalized sum = 1.0000`);

  // arrows
  arrowWithLabel(gs, CX, bar1Y + VEC_H / 2 + 10, CX, maskY - 20,
    COLORS.topk.stroke, 'apply mask', 'start');
  arrowWithLabel(gs, CX, maskY + 20, CX, bar2Y - VEC_H / 2 - 8,
    COLORS.topk.stroke, '÷ sum(top-k)', 'end');

  // deterministic sample: choose highest among top-k (makes screenshot stable)
  const sampleRank = 0;
  const sampleIdx = sortedIdx[sampleRank];

  scalarBlock(gs, CX, sampleY, `token ${sampleIdx}`, `renorm p=${renormFull[sampleRank].toFixed(3)}`, COLORS.topk.fill, COLORS.topk.stroke);
  arrowWithLabel(gs, CX, bar2Y + VEC_H / 2 + 10, CX, sampleY - SCALAR_SIZE / 2 - 6,
    COLORS.topk.stroke, 'sample', 'middle');

  shapeEq(gs, CX, sampleY + SCALAR_SIZE / 2 + 32,
    `kept_i = rank(i) < ${topK};  masked_i = kept_i · probs_i;  sample ~ softmax(masked)`, COLORS.topk.stroke);
  sampleNote(gs, CX, sampleY + SCALAR_SIZE / 2 + 32 + 28,
    `limits candidates to the ${topK} most likely tokens before sampling`, COLORS.topk.stroke);

  const step = makeStep(stepId, 'Top-K', 'Top-K Sampling',
    `topk_vals, topk_idx = probs.topk(${topK}); sample from softmax(topk_vals)`,
    `Top-K sampling first keeps only the k most probable tokens, sets all others to zero probability, re-normalizes, and then samples. This prevents the model from choosing very unlikely tokens while still allowing diversity.`,
    'step-topk', COLORS.topk.stroke, COLORS.topk.fill,
    [`topk_vals, topk_idx = probs.topk(${topK})`, `sample = torch.multinomial(softmax(topk_vals), 1)`]);

  return { step, y: sampleY + SCALAR_SIZE / 2 + 32 + 28 + SHAPE_GAP + STEP_GAP };
}

function renderTopPStep(g: Gsel, yStart: number, showV: number,
  probs: number[], topP: number): { step: DecodeStep; y: number } {
  const stepId = 6;
  const gs = startGroup(g, 'step-topp', stepId);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Top-P (Nucleus) Sampling',
    `keep smallest set with cumulative prob ≥ ${topP}`,
    COLORS.topp.fill, COLORS.topp.stroke);
  const rowY = hBottom + BOX_TO_ROW;

  const sortedIdx = argsortDesc(probs);
  const sortedProbs = sortedIdx.slice(0, showV).map((i) => probs[i]);
  const cumsum: number[] = [];
  sortedProbs.reduce((s, p, i) => { cumsum[i] = s + p; return s + p; }, 0);
  const cutoff = cumsum.findIndex((c) => c >= topP) + 1;
  const k = Math.max(1, cutoff);

  const baseColors = probColors(sortedProbs, COLORS.probs.stroke);
  const barColors = sortedIdx.slice(0, showV).map((_, rank) =>
    rank < k ? baseColors[rank] : '#f5f5f5'
  );

  const barY = rowY;
  const chartY = barY + 95;
  const sampleY = chartY + 120;

  tokenBar(gs, CX, barY, sortedProbs, barColors,
    undefined,
    `nucleus = top-${k} tokens whose cumsum reaches ${topP}`);
  smallNote(gs, CX, barY - VEC_H / 2 - 24, 'sorted probabilities', COLORS.topp.stroke, 'middle');

  // cumulative curve: y-axis scaled to topP so the crossing is always visible
  const chartH = 80;
  const chartW = VEC_W;
  const chartLeft = CX - chartW / 2;
  const yMax = topP;
  g.append('rect').attr('x', chartLeft).attr('y', chartY).attr('width', chartW).attr('height', chartH)
    .attr('fill', '#fff').attr('stroke', COLORS.topp.stroke).attr('stroke-width', 0.5).attr('rx', 4);
  const stepW = chartW / showV;
  let path = `M ${chartLeft} ${chartY + chartH}`;
  for (let i = 0; i <= showV; i++) {
    const x = chartLeft + i * stepW;
    const y = Math.max(chartY, chartY + chartH - ((cumsum[i - 1] ?? 0) / yMax) * chartH);
    path += ` L ${x} ${y}`;
  }
  g.append('path').attr('d', path).attr('fill', 'none').attr('stroke', COLORS.topp.stroke).attr('stroke-width', 2);
  const thresholdY = chartY + chartH - (topP / yMax) * chartH;
  g.append('line')
    .attr('x1', chartLeft).attr('y1', thresholdY)
    .attr('x2', chartLeft + chartW).attr('y2', thresholdY)
    .attr('stroke', COLORS.topp.stroke).attr('stroke-width', 1).attr('stroke-dasharray', '4 3');
  smallNote(gs, chartLeft + chartW - 8, thresholdY - 8, `p=${topP}`, COLORS.topp.stroke, 'end');
  smallNote(gs, chartLeft + 8, chartY + chartH - 8, '0', COLORS.topp.stroke, 'start');
  smallNote(gs, chartLeft - 8, thresholdY - 8, 'cumsum', COLORS.topp.stroke, 'end');

  // vertical cutoff line from bar down through cumulative chart
  const cellW = VEC_W / showV;
  const leftX = CX - VEC_W / 2;
  const cutoffX = leftX + k * cellW;
  g.append('line')
    .attr('x1', cutoffX).attr('y1', barY - VEC_H / 2 - 10)
    .attr('x2', cutoffX).attr('y2', chartY + chartH)
    .attr('stroke', COLORS.topp.stroke).attr('stroke-width', 2).attr('stroke-dasharray', '4 3');

  const sampleIdx = sortedIdx[0];
  scalarBlock(gs, CX, sampleY, `token ${sampleIdx}`, `nucleus p=${(cumsum[k - 1]).toFixed(3)}`, COLORS.topp.fill, COLORS.topp.stroke);
  arrowWithLabel(gs, CX, chartY + chartH + 8, CX, sampleY - SCALAR_SIZE / 2 - 6,
    COLORS.topp.stroke, 'sample within nucleus', 'start');

  shapeEq(gs, CX, sampleY + SCALAR_SIZE / 2 + 32,
    `nucleus = { i | cumsum(sort_desc(probs))_i ≤ ${topP} }; sample within nucleus`, COLORS.topp.stroke);
  sampleNote(gs, CX, sampleY + SCALAR_SIZE / 2 + 32 + 28,
    `adapts candidate set size to distribution sharpness`, COLORS.topp.stroke);

  const step = makeStep(stepId, 'Top-P', 'Top-P (Nucleus) Sampling',
    `sorted = probs.sort(desc); cumsum = sorted.cumsum(); sample where cumsum ≤ ${topP}`,
    `Top-P sampling keeps the smallest set of most likely tokens whose cumulative probability reaches p. Unlike Top-K, the set size adapts dynamically: sharp distributions use fewer candidates, flat distributions use more.`,
    'step-topp', COLORS.topp.stroke, COLORS.topp.fill,
    [`sorted_p, sorted_i = probs.sort(descending=True)`, `cumsum = sorted_p.cumsum()`, `mask = cumsum <= ${topP}`, `sample = torch.multinomial(softmax(sorted_p[mask]), 1)`]);

  return { step, y: sampleY + SCALAR_SIZE / 2 + 32 + 28 + SHAPE_GAP + STEP_GAP };
}

function renderBeamStep(g: Gsel, yStart: number, fullV: number, probs: number[],
  beamWidth: number): { step: DecodeStep; y: number } {
  const stepId = 7;
  const gs = startGroup(g, 'step-beam', stepId);
  const hBottom = stepHeader(gs, CX, yStart, stepId, 'Beam Search',
    `keep top-${beamWidth} partial hypotheses by joint log-probability`,
    COLORS.beam.fill, COLORS.beam.stroke);
  const rowY = hBottom + BOX_TO_ROW;

  const sortedIdx = argsortDesc(probs);
  const beams = sortedIdx.slice(0, beamWidth).map((idx) => ({ idx, logp: Math.log(probs[idx] + 1e-12) }));

  // layout constants (adaptive so wider trees still fit)
  const level1Spacing = Math.min(300, Math.floor((W - 160) / Math.max(1, beamWidth - 1)));
  const candidateSpacing = Math.min(70, Math.floor(level1Spacing / (beamWidth + 1)));
  const w1 = 86;
  const h1 = 50;
  const w2 = 56;
  const h2 = 40;

  const rootX = CX;
  const rootY = rowY;
  const level1Y = rootY + 100;
  const candidateY = level1Y + 120;
  const pruneY = candidateY + 75;
  const keptY = pruneY + 90;

  function beamNode(cx: number, cy: number, token: string, score: string,
    w: number, h: number, fill: string, stroke: string, textSize: number): void {
    gs.append('rect')
      .attr('x', cx - w / 2).attr('y', cy - h / 2)
      .attr('width', w).attr('height', h)
      .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
    lbl(gs, cx, cy - 3, token, { size: textSize, weight: '700', color: stroke, anchor: 'middle' });
    smallNote(gs, cx, cy + h / 2 + 11, score, stroke, 'middle');
  }

  // root start token
  gs.append('circle').attr('cx', rootX).attr('cy', rootY).attr('r', 14)
    .attr('fill', COLORS.beam.fill).attr('stroke', COLORS.beam.stroke).attr('stroke-width', 2);
  lbl(gs, rootX, rootY + 1, '⟨s⟩', { size: 11, weight: '700', color: COLORS.beam.stroke, anchor: 'middle' });
  smallNote(gs, rootX, rootY + 30, 'start token', COLORS.beam.stroke, 'middle');

  // level 1: top beamWidth tokens become initial beams
  const level1X: number[] = [];
  beams.forEach((b, i) => {
    const x = CX - (beams.length - 1) * level1Spacing / 2 + i * level1Spacing;
    level1X.push(x);
    beamNode(x, level1Y, `t${b.idx}`, `log p=${b.logp.toFixed(2)}`, w1, h1, COLORS.beam.fill, COLORS.beam.stroke, 12);
    drawArrow(g as Sel, rootX, rootY + 14 + 6, x, level1Y - h1 / 2 - 6, { color: COLORS.beam.stroke });
  });
  smallNote(gs, CX, level1Y - h1 / 2 - 36,
    `initial beams = top-${beamWidth} tokens from vocabulary`, COLORS.beam.stroke, 'middle');

  // level 2: each beam expands to beamWidth candidate next-tokens
  type Candidate = { x: number; score: number; token: string; parentIdx: number; childIdx: number; rank: number };
  const candidates: Candidate[] = [];
  beams.forEach((b, i) => {
    const parentX = level1X[i];
    const rng = makeLCG(42 + i * 1000);
    for (let j = 0; j < beamWidth; j++) {
      const nextIdx = Math.floor(rng() * fullV);
      const childLogp = Math.log((probs[nextIdx] || 1e-4) + 1e-12);
      const score = b.logp + childLogp;
      const x = parentX - (beamWidth - 1) * candidateSpacing / 2 + j * candidateSpacing;
      const token = `t${b.idx},t${nextIdx}`;
      candidates.push({ x, score, token, parentIdx: i, childIdx: nextIdx, rank: -1 });
      beamNode(x, candidateY, token, `${score.toFixed(2)}`, w2, h2, '#fff', COLORS.beam.stroke, 9);
      drawArrow(g as Sel, parentX, level1Y + h1 / 2 + 6, x, candidateY - h2 / 2 - 6, { color: COLORS.beam.stroke });
    }
  });
  smallNote(gs, CX, candidateY - h2 / 2 - 32,
    `each beam expands to ${beamWidth} candidates`, COLORS.beam.stroke, 'middle');

  // rank and keep top beamWidth candidates
  candidates.sort((a, b) => b.score - a.score);
  candidates.forEach((c, i) => { c.rank = i; });
  const kept = candidates.slice(0, beamWidth);

  // highlight the surviving candidates before pruning
  kept.forEach((k) => {
    beamNode(k.x, candidateY, k.token, `${k.score.toFixed(2)}`, w2, h2, COLORS.beam.fill, COLORS.beam.stroke, 9);
  });

  // explicit prune operation
  smallNote(gs, CX, pruneY - 26, 'select highest joint log-probability', COLORS.beam.stroke, 'middle');
  opBox(gs, CX, pruneY, `prune to top-${beamWidth}`, COLORS.beam.stroke);

  // surviving beams after pruning: keep approximate candidate x but enforce minimum spacing
  const minKeptSpacing = w1 + 24;
  const keptByX = kept.map((k, i) => ({ ...k, origIndex: i })).sort((a, b) => a.x - b.x);
  const keptXs = keptByX.map((k) => k.x);
  for (let iter = 0; iter < 10; iter++) {
    let moved = false;
    for (let i = 0; i < keptXs.length - 1; i++) {
      const diff = keptXs[i + 1] - keptXs[i];
      if (diff < minKeptSpacing) {
        const shift = (minKeptSpacing - diff) / 2;
        keptXs[i] -= shift;
        keptXs[i + 1] += shift;
        moved = true;
      }
    }
    if (!moved) break;
  }
  keptByX.forEach((k, i) => {
    const kx = keptXs[i];
    beamNode(kx, keptY, k.token, `score=${k.score.toFixed(2)}`, w1, h1, COLORS.beam.fill, COLORS.beam.stroke, 11);
    drawArrow(g as Sel, k.x, candidateY + h2 / 2 + 6, kx, keptY - h1 / 2 - 6, { color: COLORS.beam.stroke });
  });
  smallNote(gs, CX, keptY - h1 / 2 - 22, 'surviving beams after pruning', COLORS.beam.stroke, 'middle');

  // legend (top-right, clear of the tree)
  const legendX = CX + 340;
  const legendY = rootY + 10;
  gs.append('rect').attr('x', legendX - 7).attr('y', legendY - 10).attr('width', 14).attr('height', 10)
    .attr('rx', 2).attr('fill', '#fff').attr('stroke', COLORS.beam.stroke).attr('stroke-width', 1);
  smallNote(gs, legendX + 12, legendY - 5, 'candidate', COLORS.beam.stroke, 'start');
  gs.append('rect').attr('x', legendX - 7).attr('y', legendY + 14).attr('width', 14).attr('height', 10)
    .attr('rx', 2).attr('fill', COLORS.beam.fill).attr('stroke', COLORS.beam.stroke).attr('stroke-width', 1);
  smallNote(gs, legendX + 12, legendY + 19, 'kept beam', COLORS.beam.stroke, 'start');

  shapeEq(gs, CX, keptY + h1 / 2 + 36,
    `score(seq) = Σ log p(token | prefix); keep top-${beamWidth} by score`, COLORS.beam.stroke);
  sampleNote(gs, CX, keptY + h1 / 2 + 36 + 28,
    `explores multiple hypotheses jointly — higher quality, more computation`, COLORS.beam.stroke);

  const step = makeStep(stepId, 'Beam', 'Beam Search',
    `keep top-${beamWidth} hypotheses by joint log-probability`,
    `Beam search maintains ${beamWidth} partial sequences, expands each candidate, scores sequences by the sum of log probabilities, and keeps only the top ${beamWidth}. It improves output quality at the cost of increased computation and reduced diversity.`,
    'step-beam', COLORS.beam.stroke, COLORS.beam.fill,
    [`beams = [("", 0.0)]`, `for step in range(max_len):`, `  candidates = expand_all(beams)`, `  beams = top_k(candidates, ${beamWidth})`]);

  return { step, y: keptY + h1 / 2 + 36 + 28 + SHAPE_GAP + STEP_GAP };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer
// ═══════════════════════════════════════════════════════════════════════════════

export function renderDecodingStrategiesDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const variant = String(params.variant || 'all') as DecodeVariant;
  const fullV = Number(params.vocab_size || 32000);
  const showV = Math.min(fullV, 16);
  const temperature = Number(params.temperature || 0.8);
  const topK = Number(params.top_k || 50);
  const topP = Number(params.top_p || 0.9);
  const beamWidth = Number(params.beam_width || 3);

  // Deterministic, illustration-friendly logits / probs for stable screenshots
  const { logits, scaled, probs } = makeDecodingProbs(fullV, temperature);

  const steps: DecodeStep[] = [];
  let y = 28;

  // Title / param summary
  g.append('text')
    .attr('x', CX).attr('y', y).attr('text-anchor', 'middle')
    .attr('font-size', 18).attr('font-weight', 600).attr('fill', 'var(--text)')
    .text('Decoding Strategies — from logits to next token');
  y += 30;

  const summaryItems = [
    `variant: ${variant}`,
    `vocab: ${fullV}`,
    `T: ${temperature}`,
    variant === 'topk' || variant === 'all' ? `top_k: ${topK}` : '',
    variant === 'topp' || variant === 'all' ? `top_p: ${topP}` : '',
    variant === 'beam' || variant === 'all' ? `beam: ${beamWidth}` : '',
  ].filter(Boolean);
  const summaryW = W - 160;
  g.append('rect').attr('x', CX - summaryW / 2).attr('y', y).attr('width', summaryW).attr('height', 34)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = summaryW / summaryItems.length;
  summaryItems.forEach((item, i) => {
    lbl(g, CX - summaryW / 2 + segW * (i + 0.5), y + 17, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  y += 50;

  // Shared pipeline steps
  const inputRes = renderInputStep(g, y, fullV, showV, logits);
  steps.push(inputRes.step);
  y = inputRes.y;

  const tempRes = renderTemperatureStep(g, y, fullV, showV, logits, scaled, temperature);
  steps.push(tempRes.step);
  y = tempRes.y;

  const softmaxRes = renderSoftmaxStep(g, y, fullV, showV, scaled, probs);
  steps.push(softmaxRes.step);
  y = softmaxRes.y;

  // Variant-specific steps
  if (variant === 'all' || variant === 'greedy') {
    const r = renderGreedyStep(g, y, fullV, showV, probs);
    steps.push(r.step);
    y = r.y;
  }
  if (variant === 'all' || variant === 'topk') {
    const r = renderTopKStep(g, y, fullV, showV, probs, topK);
    steps.push(r.step);
    y = r.y;
  }
  if (variant === 'all' || variant === 'topp') {
    const r = renderTopPStep(g, y, showV, probs, topP);
    steps.push(r.step);
    y = r.y;
  }
  if (variant === 'all' || variant === 'beam') {
    const r = renderBeamStep(g, y, fullV, probs, beamWidth);
    steps.push(r.step);
    y = r.y;
  }

  // Insight / perf explanations
  const insightText =
    'Greedy decoding is deterministic and fast but often repetitive. Top-K and Top-P introduce stochasticity by restricting sampling to high-probability tokens. ' +
    'Top-P adapts the candidate set size to the distribution, while Top-K uses a fixed cutoff. Beam search explores multiple hypotheses jointly for higher quality.';
  y = drawExplanation(g as Sel, CX, y, W - 120, insightText, 'insight');

  const perfText =
    `Temperature ${temperature < 1 ? '< 1 sharpens' : temperature > 1 ? '> 1 flattens' : '= 1 leaves unchanged'} the distribution. ` +
    'Greedy is cheapest (one argmax). Top-K/Top-P add sampling cost but little memory. Beam search multiplies computation and memory by beam width, making it suitable for short high-quality outputs.';
  y = drawExplanation(g as Sel, CX, y, W - 120, perfText, 'perf');

  // Related component links
  drawComponentLink(g as Sel, CX - 220, y + 30, 200, 46, 'softmax', 'Softmax');
  drawComponentLink(g as Sel, CX + 20, y + 30, 200, 46, 'lm-head', 'LM Head');
  y += 90;

  // Code annotation
  y = drawCodeAnnotation(g as Sel, CX, y, W - 120,
    'Decoding Strategies — Greedy, Top-K, Top-P, Beam',
    [
      'Greedy: deterministic argmax.',
      'Top-K: fixed-size candidate set.',
      'Top-P: dynamic nucleus by cumulative probability.',
      'Beam: jointly score and prune partial sequences.',
    ],
    [
      '# Greedy',
      'token = logits.argmax(dim=-1)',
      '',
      '# Top-K',
      `topk_vals, topk_idx = logits.topk(${topK})`,
      'token = topk_idx[torch.multinomial(softmax(topk_vals / T), 1)]',
      '',
      '# Top-P',
      'sorted_p, sorted_i = probs.sort(descending=True)',
      `mask = sorted_p.cumsum(dim=-1) <= ${topP}`,
      'token = sorted_i[torch.multinomial(softmax(sorted_p.masked_fill(~mask, -inf)), 1)]',
      '',
      '# Beam Search',
      `beams = [("", 0.0)]`,
      `for _ in range(max_len):`,
      `  beams = expand_and_prune(beams, ${beamWidth})`,
    ]);

  return { width: W, height: y + 40, steps };
}
